
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_beefvdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_beefvdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.512665330569665e+00, -4.427586574773163e+00, -4.308569755026096e+00, -4.144125953468679e+00, -3.920947117099269e+00, -3.625771032023928e+00, -3.249714522336147e+00, -2.797069862661240e+00, -2.290055112149359e+00, -1.753089433573218e+00, -1.214308456224976e+00, -7.834796417230556e-01, -6.714720595940219e-01, -5.595670411056659e-01, -4.199918466290067e-01, -2.837758051031701e-01, -1.563248695060310e-01, -5.661841789137927e-02, -1.258777067283699e-02, -1.456763369968515e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


